def serialize_chained_exception(exc, max_depth=_MAX_CHAIN_DEPTH):
    """Serialize ``exc`` and its chained exceptions into plain data.

    The result is a list in traceback display order (innermost first),
    where each entry is a dict with ``type``, ``message``, ``args_repr``,
    ``relation``, ``is_exception`` and ``suppress_context`` keys.
    ``args_repr`` distinguishes ``ValueError()`` (``"()"``) from
    ``ValueError(None)`` (``"(None,)"``), messages are obtained with a
    safe ``str()`` that never raises for faulty ``__str__``/``__repr__``,
    and non-exception ``__cause__`` values are represented as a final
    non-exception entry instead of being followed. Traversal is
    iterative, follows ``__cause__`` first, then ``__context__`` unless
    ``__suppress_context__`` is true, stops on ``None`` links, detects
    cycles by identity, and is bounded by ``max_depth`` so deep chains
    do not hit the recursion limit. ``BaseException`` subclasses such
    as ``KeyboardInterrupt`` and ``SystemExit`` are traversed like any
    other exception.
    """
    raw = []
    seen = set()
    current = exc
    relation = None
    while current is not None:
        if id(current) in seen:
            break
        if len(raw) >= max_depth:
            break
        seen.add(id(current))
        if not isinstance(current, BaseException):
            raw.append(
                {
                    "type": type(current).__name__,
                    "message": _safe_str(current),
                    "args_repr": saferepr(current),
                    "relation": relation,
                    "is_exception": False,
                    "suppress_context": False,
                }
            )
            break
        try:
            args = current.args
        except Exception:
            args = ()
        suppress_context = bool(_chain_attr(current, "__suppress_context__"))
        raw.append(
            {
                "type": type(current).__name__,
                "message": _safe_str(current),
                "args_repr": saferepr(args),
                "relation": relation,
                "is_exception": True,
                "suppress_context": suppress_context,
            }
        )
        cause = _chain_attr(current, "__cause__")
        context = _chain_attr(current, "__context__")
        if cause is not None:
            relation = _CAUSE_MESSAGE
            current = cause
        elif context is not None and not suppress_context:
            relation = _CONTEXT_MESSAGE
            current = context
        else:
            current = None
    relations = [entry["relation"] for entry in raw]
    chain = list(reversed(raw))
    for index, entry in enumerate(chain):
        if index == 0:
            entry["relation"] = None
        else:
            entry["relation"] = relations[len(raw) - index]
    return chain


def format_chained_exception(exc, max_depth=_MAX_CHAIN_DEPTH):
    """Return a traceback-style text for ``exc`` and its chain.

    See ``serialize_chained_exception`` for the traversal rules.
    """
    lines = []
    for entry in serialize_chained_exception(exc, max_depth=max_depth):
        if entry["relation"] is not None:
            lines.extend(["", entry["relation"], ""])
        if entry["is_exception"] and entry["message"]:
            lines.append("{}: {}".format(entry["type"], entry["message"]))
        elif entry["is_exception"]:
            lines.append(entry["type"])
        else:
            lines.append("{}: {}".format(entry["type"], entry["message"]))
    return "\n".join(lines)
